from __future__ import annotations


def report_css() -> str:
    return """
    :root{--paper:#fcf9f4;--paper2:#f3efe7;--ink:#1c1c19;--muted:#626b66;--line:#c9c4b8;--jade:#124537;--jade2:#2d5d4e;--gold:#725b2f;--red:#a7191b;--soft:#fffdf8}*{box-sizing:border-box}html,body{max-width:100%;overflow-x:hidden}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Noto Serif SC","Source Han Serif SC",Georgia,serif;line-height:1.72}body:before{content:"";position:fixed;inset:0;background-image:radial-gradient(#e4ded2 1px,transparent 1px);background-size:18px 18px;opacity:.7;pointer-events:none}.side-nav{position:fixed;inset:0 auto 0 0;width:232px;background:#f6f3ee;border-right:1px solid var(--line);padding:22px;z-index:3}.side-nav h1{font-size:20px;margin:0}.side-nav p,.eyebrow{color:var(--muted);font-size:13px}.side-nav nav{display:grid;gap:6px;margin-top:28px}.side-nav a{color:var(--muted);text-decoration:none;border-radius:4px;padding:8px 10px}.side-nav a:hover{background:#e9e4da;color:var(--jade)}.seal{position:absolute;bottom:22px;left:22px;border:1px solid var(--red);color:var(--red);padding:8px 12px}.workspace{margin-left:232px;min-height:100vh}.topbar{position:sticky;top:0;z-index:2;height:58px;background:rgba(252,249,244,.92);backdrop-filter:blur(10px);border-bottom:1px solid var(--line);display:flex;align-items:center;gap:18px;padding:0 28px}.topbar span{color:var(--muted);font-size:13px}.topbar div{margin-left:auto}.topbar button{border:0;background:transparent;color:var(--ink);font-size:20px;padding:6px 8px}.content{max-width:1320px;margin:0 auto;padding:28px}.hero{display:grid;grid-template-columns:1fr 260px;gap:24px;padding:28px 0;border-bottom:1px solid var(--line)}.tags span{display:inline-block;background:var(--jade);color:#fff;border-radius:2px;padding:3px 8px;margin-right:8px;font-size:12px}.hero h2{font-size:42px;line-height:1.1;margin:14px 0 8px}.hero small{display:block;color:var(--gold);font-size:18px;margin-top:8px}.hero p{margin:0;color:var(--muted)}.hero-score{text-align:right}.hero-score strong{font-size:42px;color:var(--jade)}.hero-score p{font-size:12px}.dist-bar{display:flex;height:8px;overflow:hidden;border-radius:4px;background:#e6e0d6;margin:8px 0}.seg{display:block}.seg.偏多,.seg.启动,.seg.延续{background:var(--jade2)}.seg.偏空,.seg.承压{background:var(--red)}.seg.警示,.seg.变盘{background:var(--gold)}.seg.中性,.seg.震荡{background:#9c9589}.kpis{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin:16px 0}.metric,.panel,.algorithm{background:rgba(255,253,248,.9);border:1px solid var(--line);border-radius:4px}.metric{padding:10px 12px;min-width:0}.metric span{display:block;color:var(--muted);font-size:12px}.metric strong{font-size:16px;overflow-wrap:anywhere;word-break:break-word}.panel,.algorithm{padding:22px;margin:16px 0}.panel h2,details summary{font-size:22px;margin:0 0 14px}.summary{border-left:4px solid var(--jade)}.summary p{margin:0 0 12px;font-size:16px}.timeline,.hex-grid,.evidence>div,.two-col,.stat-panels{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}.time-card,.hex-card,.evidence article,.two-col article,.stat-panel,.ref-card,.algo-item{background:var(--soft);border:1px solid var(--line);border-radius:4px;padding:16px}.time-card>span{color:var(--gold);font-size:12px;font-weight:700}.time-card h3,.hex-card h3,.ref-card h3{margin:4px 0 8px;font-size:22px}.mini-hex{border-top:1px solid #ded7c9;padding-top:10px;margin-top:10px}.mini-hex p{margin:2px 0;color:var(--muted)}.risk-line{margin:14px 0 0;color:var(--red)}.hex-card{display:grid;grid-template-columns:72px 1fr;gap:16px}.hex-lines{display:flex;flex-direction:column;gap:7px;margin-top:4px}.yao{display:block;width:58px;height:7px}.yang{background:var(--ink)}.yin{display:flex;gap:10px}.yin i{display:block;flex:1;background:var(--ink)}.omen{color:var(--red);font-weight:700}.classic-note{border-left:3px solid var(--gold);padding-left:10px;color:#40392e}.badge{display:inline-block;border:1px solid #c9d2cd;background:#eef4ef;border-radius:2px;padding:2px 7px;margin:0 6px 6px 0;font-size:12px;color:var(--jade)}.score{display:grid;grid-template-columns:140px 1fr;gap:22px;align-items:center}.score-seal{height:126px;width:126px;border-radius:50%;border:3px solid var(--red);display:grid;place-items:center;color:var(--red)}.score-seal strong{font-size:42px;line-height:1}.score-seal span{margin-top:-38px}.score-row{display:grid;grid-template-columns:64px 1fr 52px;gap:10px;align-items:center;margin:10px 0}.score-row span,.score-row strong{font-size:13px}.score-row i{height:8px;background:#e5dfd3;border-radius:4px;overflow:hidden}.score-row b{display:block;height:100%;background:linear-gradient(90deg,var(--jade2),var(--gold))}.breakdown{margin-top:14px;display:grid;gap:8px}.breakdown details{border-top:1px solid #ded7c9;padding-top:8px}.source-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.source-grid article{border:1px solid var(--line);background:var(--soft);padding:12px;border-radius:4px}.stat-panel>div:last-child{display:grid;grid-template-columns:repeat(auto-fit,minmax(76px,1fr));gap:8px}.stat-panel span{display:block;color:var(--muted);font-size:12px}.stat-panel strong{font-size:22px}.ref-grid,.algo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:12px;margin-top:16px}.ref-card .hex-lines{transform:scale(.76);transform-origin:left top;height:52px}.algo-item{border-left:4px solid var(--gold)}.algo-item h4{margin:0 0 8px}dl{display:grid;grid-template-columns:72px 1fr;gap:4px 10px}dt{color:var(--muted)}dd{margin:0}@media(max-width:860px){.side-nav{display:none}.workspace{margin-left:0}.topbar{padding:0 16px}.content{padding:16px}.hero,.score{grid-template-columns:1fr}.hero-score{text-align:left}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.hex-card{grid-template-columns:1fr}.score-seal{height:106px;width:106px}}
    """
